import React from "react";
import { Box, Typography, LinearProgress } from "@mui/material";
import WbSunnyIcon from "@mui/icons-material/WbSunny";
import SolarPowerIcon from "@mui/icons-material/SolarPower";
import CloudIcon from "@mui/icons-material/Cloud";
import ThunderstormIcon from "@mui/icons-material/Thunderstorm";
import AcUnitIcon from "@mui/icons-material/AcUnit";
import OpacityIcon from "@mui/icons-material/Opacity";

// /"ensoleille", "pluie", "orage", "secheresse", "neige", "tempete"
const weatherIcons = {
  ensoleille: <WbSunnyIcon sx={{ color: "#f5e276ff" }} />,
  secheresse: <SolarPowerIcon sx={{ color: "#e4b014ff" }} />,
  tempete: <CloudIcon sx={{ color: "#608192ff" }} />,
  pluie: <OpacityIcon sx={{ color: "#4fc3f7" }} />,
  orage: <ThunderstormIcon sx={{ color: "#c60ec0ff" }} />,
  neige: <AcUnitIcon sx={{ color: "#cfe8f3ff" }} />,
};

export default function MeteoWidget({ weather }) {
  if (!weather) return null;

  const { type, temperature, humidity, wind } = weather;
  const icon = weatherIcons[type] || <CloudIcon />;

  const rendementPct = Math.round(humidity * 100);

  return (
    <Box
      sx={{
        display: "flex",
        flexDirection: "column",
        gap: 1,
        p: 1,
        bgcolor: "#eef2f2",
        borderRadius: 2,
        boxShadow: "inset 0 0 3px rgba(0,0,0,0.1)",
      }}
    >
      <Box sx={{ display: "flex", alignItems: "center", gap: 1 }}>
        {icon}
        <Typography variant="subtitle2" sx={{ textTransform: "capitalize" }}>
          {type}
        </Typography>
      </Box>
      <Typography variant="body2" color="text.secondary">
        Température : <strong>{temperature}°C</strong>
      </Typography>
      <Typography variant="body2" color="text.secondary">
        Rendement global : <strong>{rendementPct}%</strong>
      </Typography>
      <LinearProgress
        variant="determinate"
        value={rendementPct}
        sx={{
          height: 6,
          borderRadius: 3,
          bgcolor: "rgba(0,0,0,0.05)",
          "& .MuiLinearProgress-bar": {
            bgcolor: humidity > 0.8 ? "green" : humidity > 0.5 ? "goldenrod" : "red",
          },
        }}
      />
    </Box>
  );
}
