import React, { useEffect, useRef, useState } from "react";
import { Box, Button, Divider, Typography } from "@mui/material";
import { VillageProvider } from "./hooks/VillageContext";
import MapCanvas from "./components/MapCanvas/MapCanvas";
import VillageControl from "./components/HUD/VillageControl";
import { LogProvider } from "./hooks/LogContext";


const VillageGame = () => {
  return <LogProvider>
    <VillageProvider>
    <VillageLayout />
    </VillageProvider>
    </LogProvider>
};

// Ce composant sera plus tard le "shell" du jeu Village.
// Il contient la zone de simulation (canvas) et un panneau latéral pour contrôles/debug.
const VillageLayout = () => {
 const containerRef = useRef(null);

  const [stageSize, setStageSize] = useState({ width: 0, height: 0 });
     useEffect(() => {
          const checkSize = () => {
            if (containerRef.current) {
              setStageSize({
                width: containerRef.current.offsetWidth,
                height: containerRef.current.offsetHeight,
              });
            }
          };
      
          checkSize(); // Vérification initiale
      
          // On utilise un ResizeObserver pour détecter les changements de taille
          const resizeObserver = new ResizeObserver(checkSize);
          if (containerRef.current) {
            resizeObserver.observe(containerRef.current);
          }
      
          // Nettoyage au démontage
          return () => resizeObserver.disconnect();
        }, []); // Se lance une fois au montage
         const stageCenter = {
    x: stageSize.width / 2,
    y: stageSize.height / 2,
  };
  return (
    <Box
      sx={{
        display: "flex",
        flexDirection: "row",
        width: "100vw",
        height: "100vh",
        overflow: "hidden",
        bgcolor: "#eef0e6",
      }}
    >
      {/* Zone centrale : carte / canvas */}
      <Box  ref={containerRef}
        sx={{
          flex: 1,
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          bgcolor: "#cfe0b3",
          position: "relative",
        }}
      >

          {(stageSize.width != 0 && stageSize.height != 0)&& <MapCanvas size={stageSize}/>}
      </Box>

      {/* Panneau latéral : debug / contrôles */}
      <VillageControl/>
    </Box>
  );
};

export default VillageGame;
