import { Rect } from "react-konva";


const TILE_COLORS = {
  pampa: "#d4ee8c",
  foret: "#43957d",
  prairie: "#81e945",
  eau: "#4a90e2",
  montagne: "#8b8680",
};

export default function VillageTiles({ world, images, cellSize }) {
  const tiles = [];
  const at = world.activeCommunityGoal?.target;
  for (let y = 0; y < world.map.height; y++) {
    for (let x = 0; x < world.map.width; x++) {
      const tile = world.tiles[y][x];
      const color = TILE_COLORS[tile.type] || "#ddd";
      const texture = images[tile.type];
      
      tiles.push(
        <Rect
          key={`${x}-${y}`}
          x={x * cellSize}
          y={y * cellSize}
          width={cellSize}
          height={cellSize} 
          fill={texture ? undefined : color}
          fillPatternImage={texture}
          fillPatternRepeat="repeat"
          fillPatternScaleX={cellSize / (texture?.width || 64)}
          fillPatternScaleY={cellSize / (texture?.height || 64)}
          stroke={(at?.x==x&&at.y==y)?"#F22":"#555"}
          strokeWidth={(at?.x==x&&at.y==y)?1:0.3}
        />
      );
    }
  }

  return <>{tiles}</>;
}
