import React from "react";
import { Group, Image, Rect, Text } from "react-konva";

const ResourceSprite = ({ r, cellSize, imgSrc }) => {
  const img = imgSrc;

  const ratio = Math.max(0.5, r.quantite / r.maxQuantite);
  const size = cellSize * ratio * 0.9; // un peu de dynamique visuelle selon la quantité
  const x = (r.x + 0.5) * cellSize - size / 2;
  const y = (r.y + 0.5) * cellSize - size / 2;

  const labelY = (r.y + 0.75) * cellSize;
  const labelWidth = cellSize * 0.9;
  const labelX = (r.x + 0.05) * cellSize;

  const labelText = `${r.quantite.toFixed(1)}/${r.maxQuantite}`;
  return (
    <Group key={r.id}>
      {/* Ombre sous la ressource pour relief */}
      <Rect
        x={x + 2}
        y={y + 2}
        width={size}
        height={size}
        fill="rgba(0,0,0,0.15)"
        cornerRadius={3}
      />

      {/* Image de la ressource (ou carré coloré si image absente) */}
      {img ? (
        <Image
          image={img}
          x={x}
          y={y}
          width={size}
          height={size}
          shadowBlur={3}
          shadowColor="rgba(0,0,0,0.2)"
        />
      ) : (
        <Rect
          x={x}
          y={y}
          width={size}
          height={size}
          fill="#aaa"
          cornerRadius={3}
        />
      )}

     {/* Fond du texte (pour contraste) */}
      <Rect
        x={labelX}
        y={labelY - 1}
        width={labelWidth}
        height={12}
        fill="rgba(255,255,255,0.7)"
        cornerRadius={2}
        shadowBlur={1}
      />

      {/* Texte quantité/max */}
      <Text
        x={labelX}
        y={labelY}
        text={labelText}
        fontSize={10}
        width={labelWidth}
        align="center"
        fill="#222"
      />
    </Group>
  );
};

const VillageResources = ({ resources, images, cellSize }) => {
  return (
    <>
      {resources.map((r) => (
        <ResourceSprite
          key={r.id}
          r={r}
          cellSize={cellSize}
          imgSrc={images[r.category]}
        />
      ))}
    </>
  );
};

export default VillageResources;
