import React from 'react';

export default function CommunityMonitor({ world }) {
  if (!world) return null;

  const { communityStock = {}, communityNeeds = {}, activeCommunityGoal, agents = [] } = world;

  return (
    <div style={{ 
      padding: 10, 
      background: '#222', 
      color: 'white', 
      fontFamily: 'monospace',
      borderRadius: 8, 
      width: 300 
    }}>
      <h3 style={{ marginTop: 0, color: '#9fe870' }}>🌍 Community Monitor</h3>

      {/* --- STOCK --- */}
      <section style={{ marginBottom: 10 }}>
        <strong>🏗️ Stock communautaire :</strong>
        {Object.entries(communityStock).map(([key, val]) => (
          <div key={key} style={{ display: 'flex', justifyContent: 'space-between' }}>
            <span>{key}</span><span>{val}</span>
          </div>
        ))}
      </section>

      {/* --- NEEDS --- */}
      <section style={{ marginBottom: 10 }}>
        <strong>📈 Besoins communautaires :</strong>
        {Object.entries(communityNeeds).map(([key, need]) => (
          <div key={key} style={{ margin: '2px 0' }}>
            <span style={{ width: 70, display: 'inline-block' }}>{key}</span>
            <ProgressBar value={need.value} target={need.target} />
          </div>
        ))}
      </section>

      {/* --- GOAL --- */}
      <section style={{ marginBottom: 10 }}>
        <strong>🎯 Objectif communautaire :</strong>
        {activeCommunityGoal ? (
          <div style={{ fontSize: 13, marginTop: 4 }}>
            <div><b>{activeCommunityGoal.label}</b></div>
            {activeCommunityGoal.requiredResources && (
              <div style={{ marginTop: 2 }}>
               
                {Object.keys(activeCommunityGoal.requiredResources[0]).map((r, i) => (
                  <div key={i}>
                    🔹 {r}: {activeCommunityGoal.requiredResources[0][r]} requis
                  </div>
                ))}
              </div>
            )}
            {activeCommunityGoal.buildTime && (
              <div style={{ marginTop: 4 }}>
                Progression : {activeCommunityGoal.progress ?? 0}/{activeCommunityGoal.buildTime}
              </div>
            )}
          </div>
        ) : (
          <div>Aucun objectif en cours</div>
        )}
      </section>

      {/* --- AGENTS --- */}
      <section>
        <strong>👥 Agents :</strong>
        <div style={{ display: 'flex', flexDirection: 'column', gap: 4, marginTop: 4 }}>
          {agents.map((a, i) => (
            <div key={i} style={{ 
              background: '#333', 
              padding: 4, 
              borderRadius: 4 
            }}>
              <div style={{ fontWeight: 'bold', fontSize: 13 }}>{a.name || `Agent ${i}`}</div>
              <StatLine label="Energy" value={a.energy} />
              <StatLine label="Hunger" value={a.hunger} inverse />
              <StatLine label="Bonheur" value={a.bonheur} />
              <div style={{ fontSize: 12, color: '#aaa' }}>
                Action : {a.currentAction?.name || 'Aucune'}
              </div>
            </div>
          ))}
        </div>
      </section>
    </div>
  );
}

function ProgressBar({ value = 0, target = 1 }) {
  const pct = Math.min(100, (value / target) * 100);
  return (
    <div style={{ 
      background: '#444', 
      borderRadius: 4, 
      width: '100%', 
      height: 8,
      overflow: 'hidden'
    }}>
      <div style={{ 
        width: `${pct}%`, 
        height: '100%', 
        background: pct > 90 ? '#9fe870' : '#68c0ff',
        transition: 'width 0.3s linear'
      }} />
    </div>
  );
}

function StatLine({ label, value, inverse = false }) {
  const pct = value;
  return (
    <div style={{ marginBottom: 2 }}>
      <span style={{ fontSize: 12 }}>{label}</span>
      <div style={{ 
        background: '#555', 
        height: 6, 
        borderRadius: 3, 
        overflow: 'hidden'
      }}>
        <div style={{ 
          width: `${pct}%`, 
          height: '100%', 
          background: (pct<40&&!inverse)||(pct>60&&inverse) ? '#ff7070' : '#70ff90', 
          transition: 'width 0.3s linear'
        }} />
      </div>
    </div>
  );
}
