import React from "react";
import { useLog } from "../../hooks/LogContext";

export default function VillageLogPanel() {
  const { logs } = useLog();

  return (
    <div
      style={{
        flex: 1,
        background: "#111",
        color: "#eee",
        fontFamily: "monospace",
        fontSize: "0.8rem",
        overflowY: "auto",
        padding: "0.5rem",
        borderLeft: "2px solid #333",
      }}
    >
      <strong style={{ display: "block", marginBottom: "0.5rem" }}>🪶 Journal du Village</strong>
      {logs.slice().reverse().map((log) => (
        <div key={log.id}>
          <span style={{ color: "#666" }}>{log.time} </span>
          {log.text}
        </div>
      ))}
    </div>
  );
}
