import React, { useEffect } from "react";
import { Stage, Layer, Rect, Circle, Text } from "react-konva";
import { useVillage } from "../../hooks/VillageContext";
import VillageTiles from "./VillageTiles";
import VillageResources from "./VillageResources";
import VillageBuildings from "./VillageBuildings";
import VillageAgents from "./VillageAgents";
import { usePreloadedImages } from '../../../civ/utils/hooks';
import { AllImageSources } from '../../../civ/utils/imagesImports';
import imgChamp from '../../../bactery/images/centreAgro.png'
import imgSanglier from '../../models/sanglier.png'
import imgPlace from '../../models/place.png'
import imgDortoir from '../../models/dortoir.png'
import imgMineor from '../../../civ/images/mineDor.png'
import imgMouton from '../../../civ/images/mouton.png'
import imgCharbon from '../../../bactery/images/charbon.png'
import imgForet from '../../../bactery/images/bois.png'
import imgFruit from '../../../farmer/images/raisin.png'

const MapCanvas = ({size}) => {
  const { world } = useVillage();
  const { width, height, cellSize } = world.map;
  const stageWidth =size.width;
  const stageHeight = size.height;

const imagesTiles = usePreloadedImages(AllImageSources);
const imageRessource = usePreloadedImages({mineOr:imgMineor, mineCharbon:imgCharbon
  , foret:imgForet, fruit:imgFruit, sanglier:imgSanglier, laine:imgMouton
  , dortoir:imgDortoir, place:imgPlace
})
 

  // Rendu des agents (cercles)
 
 
  return (
    <Stage width={stageWidth} height={stageHeight} draggable>
      <Layer><VillageTiles world={world} images={imagesTiles} cellSize={cellSize}/></Layer>
      <Layer><VillageResources resources={world.resources} images={imageRessource} cellSize={cellSize}/></Layer>
      <Layer><VillageBuildings buildings={world.buildings} images={imageRessource} cellSize={cellSize}/></Layer>
      <Layer><VillageAgents agents={world.agents} cellSize={cellSize}/></Layer>
    </Stage>
  );
};

export default MapCanvas;
