  creerChamp: {
  label: "Créer un champ",
  roles: ["chef"],
  conditions: (agent, world) =>
    !world.activeCommunityGoal && world.communityNeeds.food.value < 0.4,
  findTarget: (agent, world) => {
    // Cherche la meilleure tuile pour un champ
    return getBestLocation(agent, world);
   
  },
  cost: { energy: 3 },
  effect: (agent, world) => {
    const pos = agent.currentAction?.target;
    if (!pos) return;
    world.activeCommunityGoal = {
      id: `goal_champ_${Date.now()}`,
      type: "creerChamp",
      label: "Créer un champ",
      targetTile: pos,
      requiredResources: [{ wood: 5 }],
      buildTime: 5,
      effect: (w) => {
        const { x, y } = pos;
        w.resources.push({
          id: `champ_${x}_${y}`,
          type: "champ",
          category: "culture",
          x,
          y,
          quantite: 0,
          maxQuantite:10,
          productivite: 2,
        });
        for (let dy = -1; dy <= 1; dy++) {
          for (let dx = -1; dx <= 1; dx++) {
            const tx = x + dx, ty = y + dy;
            if (w.map.tiles[ty]?.[tx]) {
              w.map.tiles[ty][tx].type = 'prairie';
            }
          }
        }
        return "Le champ est terminé !";
      }
    };
    return `${agent.name} a proposé de créer un champ à (${pos.x},${pos.y})`;
  },
  desirability: (agent, world) =>
    (1 - world.communityNeeds.food.value) * 50, // plus la food est basse, plus on veut un champ
}

