import React from "react";
import { Circle, Group, Image, Rect, Text } from "react-konva";

const VillageBuildings = ({ buildings, images, cellSize }) => {
  // Génère les rectangles de la grille
  
  const ress = buildings.map((b) => {
    const img = images[b.category];

  const labelY = (b.y + 0.75) * cellSize;
  const labelWidth = cellSize * 0.9;
  const labelX = (b.x + 0.05) * cellSize;

    return <Group key={b.id}>
      {img ? (
        <Image
          image={img}
          x={b.x*cellSize}
          y={b.y*cellSize}
          width={cellSize * (b.width ?? 1)}
          height={cellSize * (b.height ?? 1)}
          shadowBlur={3}
          shadowColor="rgba(0,0,0,0.2)"
        />
      ) : (
        <Rect
          x={b.x * cellSize}
          y={b.y * cellSize}
          width={cellSize * 1.5}
          height={cellSize * 1.2}
          fill="#cfa"
          stroke="#5a4"
          strokeWidth={1.2}
          cornerRadius={3}
        />
      )}

 {/* Fond du texte (pour contraste) */}
      <Rect
        x={labelX}
        y={labelY - 1}
        width={labelWidth}
        height={12}
        fill="rgba(255,255,255,0.7)"
        cornerRadius={2}
        shadowBlur={1}
      />
      <Text
        x={labelX}
        y={labelY}
        fontSize={10}
        width={labelWidth}
        text={b.name}
        fill="#333"
      />
    </Group>
  });
  return <>{ress}</>
}
export default VillageBuildings;