export function generateTerrain(world) {
  const { tiles=[], resources } = world;

  for (const res of resources) {
    const { x, y, type } = res;
    const radius = 2; // zone d'influence

    for (let dy = -radius; dy <= radius; dy++) {
      for (let dx = -radius; dx <= radius; dx++) {
        const tx = x + dx, ty = y + dy;
        const tile = tiles[ty]?.[tx];
        if (!tile) continue;

        switch (type) {
          case 'bois':
            tile.type = 'foret';
            tile.movementCost = 1.5;
            break;
          case 'champ':
            tile.type = 'prairie';
            tile.movementCost = 1;
            break;
          case 'mine':
            tile.type = 'montagne';
            tile.movementCost = 2.5;
            break;
          case 'eau':
            tile.type = 'eau';
            tile.passable = false;
            tile.movementCost = Infinity;
            break;
          default:
            break;
        }
      }
    }
  }

  return world;
}

export function generateOrganicTerrain(world, biomeSize = 5) {
  const { map, tiles } = world;
  const {width, height} = map||{};
  
  // Grille de bruit grossière : un point tous les biomeSize tiles
  const coarseW = Math.ceil(width / biomeSize);
  const coarseH = Math.ceil(height / biomeSize);

  // Valeurs aléatoires sur la grille grossière
  const coarse = Array.from({ length: coarseH }, () =>
    Array.from({ length: coarseW }, () => Math.random())
  );

  // Fonction utilitaire d'interpolation bilinéaire
  const lerp = (a, b, t) => a + (b - a) * t;
  const bilerp = (x, y, grid) => {
    const xi = Math.floor(x);
    const yi = Math.floor(y);
    const xf = x - xi;
    const yf = y - yi;
    const a = grid[yi]?.[xi] ?? 0;
    const b = grid[yi]?.[xi + 1] ?? a;
    const c = grid[yi + 1]?.[xi] ?? a;
    const d = grid[yi + 1]?.[xi + 1] ?? a;
    return lerp(lerp(a, b, xf), lerp(c, d, xf), yf);
  };

  // Pour chaque tile du monde, on échantillonne la grille interpolée
  for (let y = 0; y < height; y++) {
    for (let x = 0; x < width; x++) {
      const n = bilerp(x / biomeSize, y / biomeSize, coarse);
//       const humidity = 0.3; // 0 sec, 1 humide Si on veut changer l'humidité
//         const n = bilerp(x / biomeSize, y / biomeSize, coarse) * (0.5 + humidity);


      let type = "pampa";
      if (n < 0.2) type = "eau";
      else if (n < 0.3) type = "prairie";
      else if (n < 0.5) type = "foret";
      else if (n < 0.65) type = "montagne";
      else type = "pampa";

      tiles[y][x].type = type;
      tiles[y][x].passable = type !== "eau";
      tiles[y][x].movementCost =
        type === "montagne" ? 2 : type === "foret" ? 1.5 : 1;
    }
  }
}


export const updateWeather = (world) => {
  const weathers = ["ensoleille", "pluie", "orage", "secheresse", "neige", "tempete"];
  if (!world.weather || Math.random() < 0.05) {
    world.weather = {
      type: weathers[Math.floor(Math.random() * weathers.length)],
      temperature: Math.round(Math.random() * 60)-15,
      humidity: Math.random(),
      wind: Math.random(),
    };
  }
};

export const spawnResource = (world, x, y, type,category) => {
  // création de la ressource
  const resource = {
    id: `res_${Date.now()}_${Math.floor(Math.random() * 1000)}`,
    type, category,
    x,
    y,
    quantite: Math.round(Math.random() * 10 + 5),
    maxQuantite:(world.completedCommunityGoals.length+1)*10,
    productivite:Math.round(Math.random() * 3 + 2),
  };
  world.resources.push(resource);

  // transformation du biome local selon le type
  const typeToSurrounding = {
    bois: "foret",
    pierre: "montagne",
    champ: "prairie",
    baie: "broussailles",
  };
  const newType = typeToSurrounding[type] ?? "prairie";

  for (let dy = -1; dy <= 1; dy++) {
    for (let dx = -1; dx <= 1; dx++) {
      const tx = x + dx;
      const ty = y + dy;
      if (world.tiles[ty]?.[tx]) {
        world.tiles[ty][tx].type = newType;
      }
    }
  }

  return resource;
};
