
// utilitaire pour piocher une case aléatoire
const randomChoice = (arr) => arr[Math.floor(Math.random() * arr.length)];

export const populateWorld = (world) => {
  const width = world.map.width;
  const height = world.map.height;
  const tiles = world.tiles.flat();

  // 1. --- Sélection des zones habitables ---
  const landTiles = tiles.filter(t => t.type !== "eau");

  // On considère le centre du monde pour les agents/bâtiments
  const centerX = Math.floor(width / 2);
  const centerY = Math.floor(height / 2);

  const getNearCenter = (radius = 5) =>
    landTiles.filter(t =>
      Math.abs(t.x - centerX) < radius &&
      Math.abs(t.y - centerY) < radius
    );

  // 2. --- Placement des agents et bâtiments ---
  const possibleStarts = [...getNearCenter(6)];

  const takeSpot = () => {
    if (!possibleStarts.length) return randomChoice(landTiles);
    const idx = Math.floor(Math.random() * possibleStarts.length);
    return possibleStarts.splice(idx, 1)[0];
  };

  world.agents = [
    { id: "gerard", name: "Gérard le connard", role: "explorateur", color: "#4a7" },
    { id: "leonie", name: "Léonie", role: "cuisinier", color: "#a47" },
    { id: "marc", name: "Marc le chasseur", role: "chasseur", color: "#47a" },
    { id: "pute", name: "Sophie la pute", role: "pute", color: "rgba(221, 100, 192, 1)" },
    { id: "chef", name: "Grand schtroumpf", role: "chef", color: "#7a4" },
  ].map(a => {
    const tile = takeSpot();
    return {
      ...a,
      x: tile.x,
      y: tile.y,
      energy: 100,
      hunger: 50,
      bonheur: 50,
      inventory: {},
      relations: {},
      state: "idle",
      dest: null,
      currentAction: null
    };
  });

  // Bâtiments : plus espacés du centre
  const buildingSpots = getNearCenter(10);
  const takeBuildingSpot = () => {
    if (!buildingSpots.length) return randomChoice(landTiles);
    const idx = Math.floor(Math.random() * buildingSpots.length);
    return buildingSpots.splice(idx, 1)[0];
  };

  world.buildings = [
    {
      id: "dortoir",
      type: "function",
      category:"dortoir",
      name: "Dortoir commun",
      level: 1,
      width:2, height:1.5,
      ...takeBuildingSpot()
    },
    {
      id: "centre",
      type: "function",
      category:"place",
      name: "Place centrale",
      level: 1,
      width:3, height:2,
      production: {
        food: { role: "cuisinier", cost: 3 }
      },
      ...takeBuildingSpot()
    }
  ];

  // 3. --- Génération des ressources ---
  const mountains = tiles.filter(t => t.type === "montagne");
  const forests = tiles.filter(t => t.type === "foret");
  const plains = tiles.filter(t => t.type !== "eau" && t.type !== "montagne");

  const makeResource = (id, type, category, tile, quantite,productivite) => ({
    id,
    type,
    category,
    x: tile.x,
    y: tile.y,
    quantite, 
    maxQuantite:quantite,
    productivite
  });

  const resources = [];
  const addSome = (tiles, count, generator) => {
    for (let i = 0; i < count; i++) {
      const tile = randomChoice(tiles);
      if (tile) resources.push(generator(tile, i));
    }
  };

  // Mines dans montagnes
  addSome(mountains, Math.max(1, width * height * 0.001), (t, i) =>
    makeResource(`mineo_${i}`, "mine", "mineOr", t, 30,1)
  );
  addSome(mountains, Math.max(1, width * height * 0.004), (t, i) =>
    makeResource(`minec_${i}`, "mine", "mineCharbon", t, 30,2)
  );

  // Bois dans forêts
  addSome(forests, Math.max(3, width * height * 0.003), (t, i) =>
    makeResource(`bois_${i}`, "bois", "foret", t, 50,2)
  );

  // Baies partout sauf eau
  addSome(plains, Math.max(5, width * height * 0.005), (t, i) =>
    makeResource(`baies_${i}`, "baies", "fruit", t, 20,3)
  );

  // Animaux sur zones mixtes
  addSome(plains, Math.max(2, width * height * 0.002), (t, i) =>
    makeResource(`animals_${i}`, "animal", "sanglier", t, 20,1)
  );
  addSome(plains, Math.max(2, width * height * 0.002), (t, i) =>
    makeResource(`animalm_${i}`, "animal", "laine", t, 20,2)
  );

  world.resources = resources;

  return world;
};
